// بتوحّد صيغ الحروف العربية المتشابهة قبل أي مقارنة نصية في البحث — عشان لو حد كتب "سباكه" بالهاء
// بدل "سباكة" بالتاء المربوطة (غلطة إملائية شائعة جدًا)، أو "إسكندرية"/"اسكندرية" بهمزات مختلفة،
// يفضل البحث لاقيهم صح. من غيرها، أي اختلاف بسيط في الحروف كان بيخلي المطابقة النصية (includes) تفشل بصمت
const normalizeArabic = (s="") => String(s)
  .replace(/[إأآا]/g, "ا")
  .replace(/ى/g, "ي")
  .replace(/ة/g, "ه")
  .replace(/[\u064B-\u065F\u0670\u0640]/g, "") // تشكيل وتطويل
  .replace(/\s+/g, " ")
  .trim()
  .toLowerCase();

// بتشيل "ال" التعريف (ومشتقاتها زي "وال"، "بال"، "فال"، "كال") من أول الكلمة، عشان "مطابخ"
// تتساوى مع "المطابخ" مثلاً
const stripArabicPrefix = (w="") => w.replace(/^(و|ف|ب|ك|ل)?ال/, "") || w;

// مطابقة على مستوى الكلمات لا النص الكامل — عشان التخصصات "المشتقة" اللي مكتوبة بصياغة مختلفة
// أو بترتيب كلمات مختلف عن التصنيف الأساسي (زي حد يدوّر على "تركيب مطابخ" ويلاقي عضو كاتب تخصصه
// "تركيب المطابخ والدواليب") لسه تتلاقي، بدل ما تفشل بسبب فرق حرف "ال" أو ترتيب الكلمات
// // ARABIC_SMART_SEARCH_V2
// مرادفات شائعة في سوق التشطيبات + تحمل خطأ إملائي بسيط، عشان العميل مش لازم يكتب
// اسم التخصص بنفس الصياغة المسجلة حرفياً. مثال: نقاش/دهانات، كهربا/كهربائي، سباك/سباكة.
const SEARCH_TOKEN_CANON = {
  "كهربا":"كهرباء", "كهرباء":"كهرباء", "كهربائي":"كهرباء", "كهرباي":"كهرباء",
  "سباك":"سباكه", "سباكه":"سباكه", "سباكي":"سباكه", "صحي":"سباكه",
  "نقاش":"دهانات", "نقاشه":"دهانات", "دهان":"دهانات", "دهانات":"دهانات", "دوكو":"دهانات",
  "محار":"محاره", "محاره":"محاره", "مبيض":"محاره", "بياض":"محاره",
  "نجار":"نجاره", "نجاره":"نجاره", "خشب":"نجاره",
  "حداد":"حداده", "حداده":"حداده", "حديد":"حداده",
  "سيراميك":"سيراميك", "بلاط":"سيراميك", "مبلط":"سيراميك",
  "تكييف":"تكييف", "تكييفات":"تكييف", "تبريد":"تكييف", "مكيف":"تكييف",
  "جبسون":"جبس", "جيبس":"جبس", "جبس":"جبس",
  "الوميتال":"الومنيوم", "الومنيوم":"الومنيوم", "المونيوم":"الومنيوم",
  "رخام":"رخام", "جرانيت":"رخام",
  "ايبوكسي":"ايبوكسي", "ابوكسي":"ايبوكسي", "epoxy":"ايبوكسي",
  "تشطيب":"تشطيبات", "تشطيبات":"تشطيبات", "ديكور":"تشطيبات",
  "مقاول":"مقاولات", "مقاولات":"مقاولات",
  "مهندس":"هندسه", "هندسه":"هندسه"
};

const canonicalSearchToken = (w="") => {
  const token = stripArabicPrefix(normalizeArabic(w));
  return SEARCH_TOKEN_CANON[token] || token;
};

const oneEditAway = (a="", b="") => {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1 || Math.max(a.length,b.length) < 5) return false;
  let i=0, j=0, edits=0;
  while (i<a.length && j<b.length) {
    if (a[i] === b[j]) { i++; j++; continue; }
    if (++edits > 1) return false;
    if (a.length > b.length) i++;
    else if (b.length > a.length) j++;
    else { i++; j++; }
  }
  if (i<a.length || j<b.length) edits++;
  return edits <= 1;
};

const arabicTextIncludes = (haystack="", needle="") => {
  const hTokens = normalizeArabic(haystack).split(" ").filter(Boolean).map(canonicalSearchToken);
  const nTokens = normalizeArabic(needle).split(" ").filter(Boolean).map(canonicalSearchToken);
  if (nTokens.length === 0) return true;
  if (hTokens.length === 0) return false;
  return nTokens.every(nt => hTokens.some(ht =>
    ht === nt || ht.includes(nt) || nt.includes(ht) || oneEditAway(ht, nt)
  ));
};

