const MemberCard = ({ member, onClick, dark }) => {
  const professionCode=member.profession||member.category||(!PLANS[member.type]?member.type:'');
  const business=['company','supplier','developer','contractor'].includes(professionCode);
  const profession={company:'شركة',supplier:'مورد',developer:'مطور عقاري',contractor:'مقاول',engineer:'مهندس',craftsman:'صنايعي',technician:'فني'}[professionCode] || 'متخصص';
  const cover=member.coverUrl||member.workPhotos?.[0];
  const reviewCount=Number(member.rating)>0?(Number(member.reviews)||0):0;
  const phone=String(member.phone||'').replace(/[^+\d]/g,'');
  const wa=String(member.whatsapp||phone).replace(/\D/g,'').replace(/^00/,'');
  const whatsapp=wa.startsWith('0')?'20'+wa.slice(1):wa;
  const track=kind=>Promise.resolve(DB.trackStat(member.id,kind)).catch(()=>{});
  return <article className={`professional-card directory-person-card ${business?'business-card':''} ${dark?'person-dark':''}`}>
    <button type="button" className="person-cover" onClick={()=>onClick(member)} aria-label={`عرض ملف ${member.name}`}>
      {cover?<img src={cover} alt={`من أعمال ${member.name}`} loading="lazy"/>:<div className="person-cover-placeholder" aria-hidden="true">{business?'▦':'⚒'}</div>}
      <span className="person-role">{profession}</span>
      {member.available===true&&<span className="person-available">● متاح للتواصل</span>}
    </button>
    <div className="person-info">
      <div className="person-identity"><Av text={member.name} size={47} type={getMemberPlan(member)} src={member.avatarUrl}/><div><h3><button type="button" onClick={()=>onClick(member)}>{member.name}</button></h3><p>{member.specialty||profession}</p></div></div>
      <div className="person-location">⌖ {[member.gov,member.city].filter(Boolean).join(' — ')||'المنطقة غير محددة'}</div>
      <p className="person-bio">{member.bio||'اطّلع على الملف والأعمال وتواصل لمعرفة تفاصيل الخدمة.'}</p>
      <div className="person-evidence">{Number(member.experience)>0&&<span>{member.experience} سنة خبرة</span>}{member.workPhotos?.length>0&&<span>{member.workPhotos.length} من صور الأعمال</span>}{['vip','premium','company','elite'].includes(getMemberPlan(member))&&<span className="person-plan">{PLANS[getMemberPlan(member)]?.label||"عضو مميز"}</span>}</div>
      <div className="person-rating">{reviewCount>0?<>★ <strong>{Number(member.rating||0).toFixed(1)}</strong><span>من {reviewCount} تقييم</span></>:<span>لا توجد تقييمات بعد</span>}</div>
      <button type="button" className="btn btn-navy person-details" onClick={()=>onClick(member)}>عرض الملف والأعمال <span>←</span></button>
      <div className="person-contact">{whatsapp&&<a href={`https://wa.me/${whatsapp}?text=${encodeURIComponent('مرحبًا، شاهدت ملفك في الدليل الشامل وأريد الاستفسار عن خدماتك')}`} target="_blank" rel="noopener noreferrer" onClick={()=>track('waMessages')}>واتساب ↗</a>}{phone&&<a href={`tel:${phone}`} onClick={()=>track('calls')}>اتصال ☎</a>}</div>
    </div>
  </article>;
};

